def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None
    stack = [(start, [start])]
    while stack:
        (node, path) = stack.pop()
        for next_node in graph[node] - set(path):
            if next_node == goal:
                return path + [next_node]
            else:
                stack.append((next_node, path + [next_node]))
    return None

