def find_path(graph, start, goal):
    # Initialize the path stack and explored nodes set
    stack = [(start, [start])]  # (path, current node)
    explored = set()

    while stack:
        (path, node) = stack.pop()
        if node not in explored:
            explored.add(node)
            if node == goal:
                return path
            else:
                for neighbor in graph.get(node, []):
                    if neighbor not in explored:
                        stack.append((path + [neighbor], neighbor))
    return None
