    def _find_path(visited, current_node, goal):
        if current_node == goal:
            return [goal]
        for neighbor in graph[current_node]:
            if neighbor not in visited:
                visited.add(neighbor)
                path = _find_path(visited, neighbor, goal)
                if path:
                    return [current_node] + path
        return None

    visited = set([start])
    return _find_path(visited, start, goal)
