def find_path(graph, start, goal):
    # Initialize the stack for DFS
    stack = [(start, [start])]
    visited = set()

    while stack:
        (vertex, path) = stack.pop()
        if vertex in visited:
            continue
        visited.add(vertex)

        # If the current vertex is the goal, return the path
        if vertex == goal:
            return path

        # Otherwise, add the unvisited neighbors to the stack
        for neighbor in graph.get(vertex, []):
            if neighbor not in visited:
                stack.append((neighbor, path + [neighbor]))

    # If the goal is unreachable, return None
    return None
