def find_path(graph, start, goal):
    # Initialize the path and visited set
    path = []
    visited = set()

    def explore(node):
        if node in visited:
            return False
        visited.add(node)
        if node == goal:
            return True
        for neighbor in graph.get(node, []):
            if explore(neighbor):
                path.append(node)
                return True
        return False

    if explore(start):
        return path
    else:
        return None
